  const settings = (n, o = {}) => desk(page(`${h1('Settings', { size: 30 })}<div style="display:flex;gap:${n ? 20 : 32}px;min-height:0"><div style="width:${n ? 320 : 380}px;flex-shrink:0;display:flex;flex-direction:column;gap:12px">${setGroup(rowx(`${Av('Lennox Emmanuel', 'lilac', 46)}${two(`<span style="display:flex;gap:5px;align-items:center">Lennox Emmanuel${tick('creator', 15)}</span>`, 'lennox@wawu.africa · 0803 ••• 4412')}<div style="flex:1"></div>${I('ChevronRight', 18, 'var(--text-muted)')}`, 12, 'padding:8px 10px'))}${setGroup(setRow('Bell', 'Notifications', '', { sel: true, trail: '' }) + setRow('Lock', 'Privacy') + setRow('KeyRound', 'Password') + setRow('BadgeCheck', 'Your tier') + setRow('Ticket', 'Access code', n ? '' : 'Claim a plan you paid for at an event') + setRow('Wallet', 'Wallet and PIN', 'PIN and account details') + setRow('Coins', 'Accounts and currencies', n ? '' : 'Your accounts, and add a currency'))}${setGroup(setRow('Palette', 'Theme', '', { trail: `<span style="font-size:14px;color:var(--text-muted);display:flex;gap:4px;align-items:center">System${I('ChevronRight', 16, 'var(--text-muted)')}</span>` }) + setRow('Info', 'About Who Made This?') + setRow('Scale', 'Legal'))}<div style="padding:2px 12px;display:flex;align-items:center;gap:20px"><span style="font-size:15px;font-weight:600;color:var(--danger)">Sign out</span><span style="font-size:13.5px;color:var(--text-muted)">Delete account</span></div></div><div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:18px">${h1('Notifications', { size: 22 })}${swGroup('Money', [['Money in', 'Tips, sales, transfers', true], ['Refunds', '', true]])}${swGroup('Messages', [['Paid questions', 'Including reply deadlines', true], ['Community messages', '', false]])}${swGroup('Content', [['Reviews', 'Approved or sent back', true], ['New followers', '', true], ['From Who Made This?', 'News and offers', false]])}</div></div>`, { gap: 20, pad: n ? '22px 24px' : '26px 36px' }), { nav: 'settings', url: 'usewmt.com/settings/notifications', narrow: n, ...o });
  const themeDialog = dialog(`${setGroup([['Monitor', 'System', true], ['Sun', 'Light', false], ['Moon', 'Dark', false]].map(([ic, t, on]) => `<div style="display:flex;align-items:center;gap:12px;min-height:56px;padding:6px 12px;border-radius:14px">${I(ic, 20)}<span style="flex:1;font-size:15px;font-weight:600">${t}</span>${radio(on)}</div>`).join(''))}`, { title: 'Theme', sub: 'System follows your computer', w: 420 });

  // ---------- Signed out: split screen
  const brandPanel = (n) => `<div style="width:${n ? 420 : 640}px;flex-shrink:0;height:100%;background:var(--surface-card-ink);position:relative;overflow:hidden;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:22px;color:#FFFFFF"><div style="position:absolute;left:-120px;top:-140px;width:520px;height:520px;border-radius:50%;background:radial-gradient(circle, rgba(148,17,201,.55), transparent 70%)"></div><div style="position:absolute;right:-160px;bottom:-180px;width:520px;height:520px;border-radius:50%;background:radial-gradient(circle, rgba(148,17,201,.35), transparent 70%)"></div><img src="brand/submark-dark.png" style="position:relative;width:${n ? 150 : 190}px"><div style="position:relative;font-size:${n ? 17 : 19}px;font-weight:600;opacity:.85;text-align:center;padding:0 30px">Create. Sell. Get paid. Connect. Grow.</div></div>`;
  const formSide = (inner) => `<div style="flex:1;min-width:0;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:30px"><div style="width:100%;max-width:420px;display:flex;flex-direction:column;gap:16px">${inner}</div></div>`;
